__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"readings",{enumerable:!0,get:function(){return o}}),Object.defineProperty(e,"contrasts",{enumerable:!0,get:function(){return s}}),Object.defineProperty(e,"probeForms",{enumerable:!0,get:function(){return n}}),Object.defineProperty(e,"sources",{enumerable:!0,get:function(){return t}});const o=[{id:"market",title:"Una ma\xf1ana en el mercado",easy:"Es s\xe1bado. Ana y Luis van al mercado. Quieren comprar fruta para la familia. Ana compra mangos. Luis no sabe c\xf3mo escoger un mango bueno. La se\xf1ora del puesto le ayuda. Despu\xe9s compran pan y regresan a casa. Luis est\xe1 contento: hoy hizo una pregunta en espa\xf1ol.",full:"El s\xe1bado por la ma\xf1ana, Ana y Luis van al mercado antes de visitar a la familia. Hay muchos puestos y se escucha m\xfasica. Ana quiere comprar mangos, pero Luis no sabe cu\xe1les escoger. Se acerca a una se\xf1ora y pregunta: \u201cDisculpe, \xbfc\xf3mo s\xe9 si un mango est\xe1 bueno?\u201d. La se\xf1ora le explica que puede olerlo y tocarlo con cuidado. Luis no entiende todo, as\xed que pide un ejemplo. Ella toma dos mangos y le muestra la diferencia. Despu\xe9s compran pan para la comida. En el camino, Luis recuerda la conversaci\xf3n. No dijo todo perfectamente, pero pudo hacer una pregunta y entender la respuesta. Al llegar a casa, le cuenta la historia a Ana otra vez, ahora en espa\xf1ol.",glosses:[["el puesto","the market stall"],["escoger","to choose"],["olerlo","to smell it"],["con cuidado","carefully"]],question:"What helps Luis understand how to choose a mango?",options:["The seller shows him two examples","Ana buys every mango","He reads a recipe"],correct:0,takeaway:"Tell the story with three ideas: where they went, the question Luis asked, and how the seller helped."},{id:"photo",title:"Una foto en la sala",easy:"En la sala hay una foto antigua. Ana est\xe1 en la foto con sus abuelos. Luis pregunta d\xf3nde estaban. Ana dice que estaban en el patio de su abuela. Cada domingo com\xedan all\xed. A Luis le gusta escuchar la historia. Pregunta qu\xe9 comida preparaba la abuela.",full:"Despu\xe9s de comer, Luis ve una foto antigua en la sala. En la foto, Ana es una ni\xf1a y est\xe1 sentada junto a sus abuelos. Detr\xe1s de ellos hay un \xe1rbol grande. Luis pregunta d\xf3nde estaban. Ana le explica que la foto es del patio de su abuela. Cuando era peque\xf1a, su familia se reun\xeda all\xed los domingos. Su abuela preparaba sopa y sus primos llegaban temprano para jugar. Un d\xeda empez\xf3 a llover durante la comida y todos tuvieron que llevar la mesa adentro. Ana se r\xede al recordarlo. Luis quiere saber m\xe1s y pregunta qu\xe9 pas\xf3 con la sopa. La abuela escucha la pregunta desde la cocina y viene a contar su parte de la historia.",glosses:[["se reun\xeda","used to get together"],["el patio","the courtyard or patio"],["adentro","inside"],["al recordarlo","when remembering it"]],question:"What brings the grandmother into the conversation?",options:["She needs to find the photograph","She hears Luis ask about the soup","She wants everyone to leave"],correct:1,takeaway:"Retell a family memory of your own. Describe the usual situation, then one thing that happened."},{id:"plan",title:"El plan cambia",easy:"La familia quiere comer en el parque el domingo. Luis va a llevar fruta. Por la ma\xf1ana llueve mucho. Ana llama a su mam\xe1. Ahora van a comer en casa. Luis pregunta a qu\xe9 hora. La comida es a las dos. Llegan temprano para ayudar.",full:"El viernes, la familia hace un plan para el domingo: comer en el parque y caminar despu\xe9s. Luis ofrece llevar fruta y Ana va a preparar agua de lim\xf3n. El domingo por la ma\xf1ana, Luis mira por la ventana. Est\xe1 lloviendo y el cielo est\xe1 muy oscuro. Ana llama a su mam\xe1 para preguntar si el plan sigue igual. Deciden comer en casa de los t\xedos. Luis escucha la conversaci\xf3n, pero no entiende la hora. En vez de adivinar, pregunta: \u201cEntonces, \xbfla comida es a las dos?\u201d. Ana confirma que s\xed. Ellos llegan media hora antes y ayudan a poner la mesa. No pueden caminar en el parque, pero pasan una tarde muy agradable contando historias.",glosses:[["sigue igual","is still the same"],["adivinar","to guess"],["media hora antes","half an hour earlier"],["agradable","pleasant"]],question:"Why does Luis ask about the time?",options:["He wants to cancel lunch","He wants to leave at two","He did not understand and wants to confirm"],correct:2,takeaway:"Describe a plan that changed. Explain the original plan, the change, and what you did instead."},{id:"recipe",title:"La receta sin medidas",easy:"Luis quiere aprender a preparar una salsa. La mam\xe1 de Ana le ense\xf1a. Ella no usa una receta escrita. Luis pregunta cu\xe1nto chile necesita. Ella dice: \u201cPrimero, solo un poco\u201d. Luis prueba la salsa. Est\xe1 buena y no pica mucho. Escribe unas notas para prepararla otra vez.",full:"A Luis le gusta mucho la salsa que prepara la mam\xe1 de Ana. Un d\xeda le pregunta si puede ense\xf1arle a hacerla. Ella acepta, pero le advierte que no tiene una receta escrita. Primero ponen tomates en una olla. Luego ella agrega un poco de chile. Luis pregunta cu\xe1nto necesita exactamente. Ella sonr\xede y dice: \u201cEmpieza con poquito; siempre puedes poner m\xe1s\u201d. Luis prueba la salsa antes de agregar m\xe1s chile. Mientras cocinan, hace preguntas cortas y escribe algunas notas. Al final, la salsa no sabe exactamente igual que la de ella, pero est\xe1 rica. La mam\xe1 de Ana le dice que la pr\xf3xima vez pueden prepararla juntos otra vez. Luis quiere explicarle la receta a su novia sin mirar sus notas.",glosses:[["las medidas","the measurements"],["una olla","a cooking pot"],["agregar","to add"],["sabe igual","tastes the same"]],question:"Why does Luis add only a little chile at first?",options:["He can taste it and add more later","There are no tomatoes","The family dislikes all spicy food"],correct:0,takeaway:"Explain a simple recipe or routine with primero, luego, and al final."},{id:"voice-note",level:"A2",title:"El mensaje de voz",easy:"Mariana le manda un mensaje de voz a Pablo. Dice: \u201c\xbfQu\xe9 onda, Pablo? Hoy no puedo ir al cine a las seis. Salgo tarde del trabajo. \xbfVamos ma\xf1ana? Ma\xf1ana estoy libre despu\xe9s de las cinco. Av\xedsame al rato, \xbfva?\u201d. Pablo escucha el mensaje dos veces. Contesta que s\xed, ma\xf1ana est\xe1 bien.",full:"Son las cuatro de la tarde cuando Pablo recibe un mensaje de voz de Mariana. Ella habla r\xe1pido y se escucha mucho ruido en la calle. \u201c\xbfQu\xe9 onda, Pablo? Oye, perd\xf3n, pero hoy no voy a poder ir al cine a las seis. Mi jefa me pidi\xf3 terminar un reporte y voy a salir tarde. \xbfQu\xe9 te parece ma\xf1ana? Ma\xf1ana estoy libre despu\xe9s de las cinco y podemos ir a la funci\xf3n de las siete. Av\xedsame al rato, \xbfva?\u201d. Pablo no entiende todo la primera vez, as\xed que escucha el mensaje otra vez. Ahora entiende el problema y la nueva hora. Le contesta con un mensaje de texto: \u201cNo te preocupes. Ma\xf1ana a las siete est\xe1 perfecto. Yo compro los boletos\u201d.",glosses:[["av\xedsame","let me know"],["al rato","in a while"],["la funci\xf3n","the showing (of a movie)"],["los boletos","the tickets"]],question:"Why can't Mariana go to the movies today?",options:["She is sick","She has to finish a report at work","She doesn't have money for tickets"],correct:1,takeaway:"Listen twice when a message is fast; the second time you hear the reason and the new time."},{id:"fonda",level:"A2",title:"La fonda de la esquina",easy:"Cerca de la oficina de Ra\xfal hay una fonda peque\xf1a. Tiene comida corrida: sopa, arroz, un guisado y agua del d\xeda. Hoy hay sopa de fideo y pollo en mole. Ra\xfal pide el men\xfa y un agua de jamaica. La comida est\xe1 rica y no es cara. Ra\xfal paga ochenta y cinco pesos.",full:"Todos los d\xedas a las dos, Ra\xfal sale de la oficina para comer. No le gusta comer solo un s\xe1ndwich, as\xed que va a la fonda de la esquina. All\xed sirven comida corrida: primero una sopa, despu\xe9s arroz, luego un guisado y al final un postre peque\xf1o. El agua del d\xeda est\xe1 incluida. La se\xf1ora que atiende ya conoce a Ra\xfal y siempre le dice qu\xe9 hay. \u201cHoy tenemos sopa de fideo o crema de elote, y de guisado hay pollo en mole o chiles rellenos\u201d. Ra\xfal pide la sopa de fideo y el mole, porque los chiles rellenos pican mucho para \xe9l. El agua del d\xeda es de jamaica. Cuando termina, pide la cuenta. Son ochenta y cinco pesos. Ra\xfal piensa que es mucho mejor que comer frente a la computadora.",glosses:[["la fonda","a small family restaurant"],["la comida corrida","the set lunch menu"],["el guisado","the main stewed dish"],["el agua del d\xeda","the fresh drink of the day"]],question:"Why doesn't Ra\xfal order the chiles rellenos?",options:["They are too expensive","There are none left","They are too spicy for him"],correct:2,takeaway:"Ask \xbfQu\xe9 hay hoy? and order by course: de sopa\u2026, de guisado\u2026"},{id:"taxi",level:"A2",title:"El viaje al aeropuerto",easy:"Sof\xeda tiene un vuelo a las once. Pide un coche por aplicaci\xf3n a las ocho. Hay mucho tr\xe1fico en el Perif\xe9rico. El chofer toma otra ruta. Llegan al aeropuerto a las nueve y media. Sof\xeda le da las gracias y una propina. Tiene tiempo para comer algo antes del vuelo.",full:"Sof\xeda tiene un vuelo a Monterrey a las once de la ma\xf1ana. Como vive lejos del aeropuerto, pide un coche por aplicaci\xf3n a las ocho en punto. El chofer llega en cinco minutos y la saluda: \u201cBuenos d\xedas, \xbfal aeropuerto, terminal uno?\u201d. Sof\xeda dice que s\xed. En la radio dicen que hay un choque en el Perif\xe9rico y que el tr\xe1fico est\xe1 muy lento. El chofer le pregunta si prefiere otra ruta por calles m\xe1s peque\xf1as. Sof\xeda acepta, aunque est\xe1 un poco nerviosa. La ruta nueva es m\xe1s larga en kil\xf3metros, pero m\xe1s r\xe1pida. Llegan a las nueve y media. Sof\xeda le da las gracias y le deja una propina. Todav\xeda tiene tiempo para tomar un caf\xe9 antes de su vuelo.",glosses:[["el vuelo","the flight"],["el chofer","the driver"],["un choque","a crash"],["la propina","the tip"]],question:"Why does the driver take a different route?",options:["There is a crash and slow traffic on the Perif\xe9rico","Sof\xeda asks for the shortest route","The terminal changed"],correct:0,takeaway:"Times and places carry a travel story: a las ocho, en el Perif\xe9rico, a las nueve y media."},{id:"chapultepec",level:"A2",title:"Un domingo en Chapultepec",easy:"El domingo Daniel y su hija van al bosque de Chapultepec. Caminan cerca del lago y ven patos. La ni\xf1a quiere un elote. Daniel compra dos elotes con lim\xf3n y chile. Despu\xe9s empieza a llover. Corren al museo y esperan all\xed. Cuando para la lluvia, regresan a casa.",full:"El domingo por la ma\xf1ana, Daniel lleva a su hija Valeria al bosque de Chapultepec. Hace sol y hay muchas familias. Primero caminan alrededor del lago y Valeria cuenta los patos: uno, dos, tres\u2026 \xa1catorce! Despu\xe9s pasan por un puesto de elotes. Valeria quiere uno con mayonesa, queso, lim\xf3n y chile, pero Daniel le dice que con poquito chile. Mientras comen, el cielo se pone gris y empieza a llover muy fuerte. Todos corren a buscar un lugar seco. Daniel y Valeria entran al Museo de Antropolog\xeda, que est\xe1 cerca. Ven las piezas antiguas mientras esperan. Una hora despu\xe9s, la lluvia para. Valeria dice que fue el mejor domingo del mes, sobre todo por la lluvia.",glosses:[["el bosque","the forest, the large park"],["los patos","the ducks"],["un elote","corn on the cob"],["seco","dry"]],question:"What do they do when it starts to rain?",options:["They go home right away","They wait in a museum","They buy umbrellas"],correct:1,takeaway:"Weather changes a plan: empieza a llover, para la lluvia, hace sol."},{id:"new-job",level:"B1",title:"El primer d\xeda en el trabajo nuevo",easy:"Era el primer d\xeda de Luc\xeda en una oficina nueva. Estaba nerviosa. Lleg\xf3 temprano, pero no sab\xeda d\xf3nde estaba su escritorio. Un compa\xf1ero le ayud\xf3. En la junta no entendi\xf3 todo, as\xed que hizo preguntas. Al final del d\xeda, estaba cansada pero contenta.",full:"Era lunes y Luc\xeda empezaba en un trabajo nuevo. La noche anterior casi no durmi\xf3 porque estaba nerviosa. Lleg\xf3 a la oficina veinte minutos antes, pero no sab\xeda a qu\xe9 piso ten\xeda que ir ni d\xf3nde estaba su escritorio. Mientras buscaba el elevador, un se\xf1or muy amable le pregunt\xf3 si era la nueva dise\xf1adora. Se llamaba Jorge y trabajaba en el mismo equipo. \xc9l le ense\xf1\xf3 la oficina y le present\xf3 a todos. A las once tuvieron una junta. Todos hablaban muy r\xe1pido y usaban palabras que Luc\xeda no conoc\xeda, pero ella decidi\xf3 preguntar en lugar de quedarse callada. Al final de la junta, la jefa le dijo que le gustaban sus preguntas. Cuando Luc\xeda sali\xf3 a las seis, estaba cansada, pero ya no estaba nerviosa.",glosses:[["la noche anterior","the night before"],["el escritorio","the desk"],["una junta","a meeting"],["quedarse callada","to stay quiet"]],question:"What did Luc\xeda decide to do in the meeting?",options:["Stay quiet and take notes","Leave early","Ask questions instead of staying quiet"],correct:2,takeaway:"Imperfect paints the scene (era, estaba, no sab\xeda); preterite tells what happened (lleg\xf3, le pregunt\xf3, decidi\xf3)."},{id:"grandma-advice",level:"B1",title:"Los consejos de la abuela",easy:"Tom\xe1s va a vivir solo por primera vez. Su abuela le da consejos. Le dice que debe comer bien y no solo comida r\xe1pida. Le recomienda cocinar los domingos para toda la semana. Tambi\xe9n le dice que debe llamar a su mam\xe1. Tom\xe1s se r\xede, pero escribe todo.",full:"Tom\xe1s consigui\xf3 un trabajo en Guadalajara y por primera vez va a vivir solo. Antes de irse, visita a su abuela, que tiene ochenta a\xf1os y muchas opiniones. \u201cMijo, deber\xedas aprender a cocinar por lo menos tres platillos. No puedes comer tacos todos los d\xedas\u201d. Tom\xe1s le contesta que en Guadalajara hay tacos muy buenos. Ella no se r\xede. \u201cTe recomiendo cocinar los domingos: haces arroz, frijoles y un guisado, y ya tienes comida para la semana\u201d. Luego le da otro consejo: \u201cEs mejor que ahorres un poco cada mes, aunque sea poquito\u201d. Al final le dice lo m\xe1s importante: \u201cY llama a tu mam\xe1, aunque est\xe9s ocupado\u201d. Tom\xe1s escribe los consejos en su tel\xe9fono. Seis meses despu\xe9s, todav\xeda cocina los domingos.",glosses:[["mijo","my son (affectionate, from mi hijo)"],["deber\xedas","you should"],["los platillos","the dishes"],["ahorrar","to save (money)"]],question:"Which advice does Tom\xe1s still follow six months later?",options:["Cooking on Sundays","Eating tacos every day","Calling his grandmother daily"],correct:0,takeaway:"Give advice three ways: deber\xedas + infinitive, te recomiendo + infinitive, es mejor que\u2026"},{id:"forgot-wallet",level:"B1",title:"Se me olvid\xf3 la cartera",easy:"Andrea va al tianguis. Compra fruta y verdura. Cuando quiere pagar, no encuentra su cartera. \xa1Se le olvid\xf3 en casa! El se\xf1or del puesto le dice que no hay problema. Andrea paga con el tel\xe9fono. Al d\xeda siguiente regresa y compra m\xe1s fruta.",full:"Los mi\xe9rcoles hay tianguis en la calle de Andrea, y ella siempre compra all\xed la fruta de la semana. Ese d\xeda escogi\xf3 mangos, pl\xe1tanos, jitomates y un kilo de aguacates. Cuando el se\xf1or le dijo el total, Andrea busc\xf3 su cartera en la bolsa, pero no estaba. Busc\xf3 otra vez. Nada. Se le hab\xeda olvidado en la mesa de la cocina. Muy apenada, le explic\xf3 al se\xf1or lo que pas\xf3 y le pregunt\xf3 si pod\xeda apartar las cosas mientras iba por dinero. El se\xf1or le dijo que no se preocupara y le pregunt\xf3 si ten\xeda transferencia en el tel\xe9fono. Andrea pag\xf3 as\xed en un minuto. Antes de irse, el se\xf1or le regal\xf3 un mango extra \u201cpor el susto\u201d. Desde ese d\xeda, Andrea revisa la bolsa antes de salir.",glosses:[["el tianguis","the open-air street market"],["apenada","embarrassed"],["apartar","to set aside, hold"],["el susto","the scare"]],question:"How does Andrea finally pay?",options:["She goes home for her wallet","With a bank transfer on her phone","The seller gives everything for free"],correct:1,takeaway:"Se me olvid\xf3, se me cay\xf3, se me perdi\xf3: Spanish frames accidents as things that happened to you."},{id:"radio-ad",level:"B1",title:"Un anuncio en la radio",easy:"En la radio hay un anuncio. Es para una clase de cocina mexicana. La clase es los s\xe1bados de diez a una. Cuesta seiscientos pesos al mes. En la clase preparan tamales, pozole y salsas. Para inscribirse, hay que mandar un mensaje antes del viernes.",full:"Mientras maneja al trabajo, Iv\xe1n escucha un anuncio en la radio: \u201c\xbfTe gustar\xeda aprender a preparar la comida de tu abuela? En la Cocina de Do\xf1a Paty te ense\xf1amos los secretos de la cocina mexicana tradicional. Este mes vamos a preparar tamales verdes, pozole rojo y tres salsas que no pueden faltar en tu mesa. Las clases son los s\xe1bados de diez de la ma\xf1ana a una de la tarde, en la colonia Roma. Grupos peque\xf1os, m\xe1ximo ocho personas. El costo es de seiscientos pesos al mes, con todos los ingredientes incluidos. \xa1Y si vienes con un amigo, los dos tienen diez por ciento de descuento! Los lugares son limitados: inscr\xedbete antes del viernes mandando un mensaje al n\xfamero que aparece en nuestra p\xe1gina\u201d. Iv\xe1n piensa en su hermana, que siempre dice que quiere aprender a hacer tamales.",glosses:[["un anuncio","an advertisement"],["no pueden faltar","can't be missing, are essential"],["el descuento","the discount"],["inscribirse","to sign up"]],question:"How could Iv\xe1n and his sister pay less?",options:["By signing up together with a friend","By bringing their own ingredients","By going on weekdays"],correct:0,takeaway:"Ads pack in times, prices, and conditions; listen for the numbers and for si\u2026"}],s=[{id:"se1",group:"ser-estar",context:"Identify Ana\u2019s profession.",sentence:"Ana ___ m\xe9dica.",options:["es","est\xe1"],correct:0,hint:"Are you identifying who Ana is, or describing her current state?",why:"Ser identifies a profession: Ana es m\xe9dica. The useful distinction is function, not simply permanent versus temporary."},{id:"se2",group:"ser-estar",context:"Locate the plates right now.",sentence:"Los platos ___ en la cocina.",options:["son","est\xe1n"],correct:1,hint:"This tells you where physical objects are.",why:"Estar locates objects: los platos est\xe1n en la cocina."},{id:"se3",group:"ser-estar",context:"Say how Luis feels after work.",sentence:"Luis ___ cansado hoy.",options:["es","est\xe1"],correct:1,hint:"Think about a present condition.",why:"Estar describes how he feels now: est\xe1 cansado."},{id:"se4",group:"ser-estar",context:"Say where the family\u2019s party takes place.",sentence:"La fiesta ___ en casa de Ana.",options:["es","est\xe1"],correct:0,hint:"An event\u2019s location works differently from an object\u2019s location.",why:"Ser gives the location of an event: la fiesta es en casa de Ana."},{id:"se5",group:"ser-estar",context:"Describe the flavor of today\u2019s soup.",sentence:"La sopa ___ muy rica.",options:["es","est\xe1"],correct:1,hint:"You are tasting this particular soup now.",why:"Est\xe1 rica evaluates the food you are tasting. Es rica can describe a food generally, but the context here is today\u2019s serving."},{id:"se6",group:"ser-estar",context:"Identify where Ana is from.",sentence:"Ana ___ de M\xe9xico.",options:["es","est\xe1"],correct:0,hint:"Origin uses the same verb as identity.",why:"Ser + de expresses origin: es de M\xe9xico."},{id:"pa1",group:"past",context:"A repeated childhood habit: every Sunday.",sentence:"De ni\xf1o, Luis ___ con sus abuelos todos los domingos.",options:["comi\xf3","com\xeda"],correct:1,hint:"Is this a habit or one completed occasion?",why:"Com\xeda describes a repeated background habit; this is not a count of completed meals."},{id:"pa2",group:"past",context:"One completed visit yesterday.",sentence:"Ayer Luis ___ a sus abuelos.",options:["visit\xf3","visitaba"],correct:0,hint:"This presents a single completed event.",why:"Visit\xf3 presents the visit as completed. A different background context could use visitaba."},{id:"pa3",group:"past",context:"Describe the weather in the background of a story.",sentence:"Cuando salimos, ___ mucho fr\xedo.",options:["hizo","hac\xeda"],correct:1,hint:"Set the scene rather than summarize the whole period.",why:"Hac\xeda fr\xedo sets the background conditions when we left."},{id:"pa4",group:"past",context:"The phone rang once while Ana was cooking.",sentence:"Ana cocinaba cuando ___ el tel\xe9fono.",options:["son\xf3","sonaba"],correct:0,hint:"Which form marks the event that interrupted the background action?",why:"Son\xf3 marks the completed interruption; cocinaba supplies the ongoing background."},{id:"pa5",group:"past",context:"Describe your town as it used to be.",sentence:"Mi pueblo ___ peque\xf1o.",options:["fue","era"],correct:1,hint:"Describe the setting, without giving a bounded whole period.",why:"Era describes a past background characteristic. Fue would require a different bounded perspective."},{id:"pa6",group:"past",context:"Report a completed meal last night.",sentence:"Anoche ___ sopa y despu\xe9s lavamos los platos.",options:["comimos","com\xedamos"],correct:0,hint:"These actions form a sequence of completed events.",why:"Comimos presents eating as completed, followed by washing the dishes."},{id:"pp1",group:"por-para",context:"Say why you are calling.",sentence:"Te llamo ___ preguntarte algo.",options:["por","para"],correct:1,hint:"Think about the goal of the call.",why:"Para + infinitive gives a purpose: te llamo para preguntarte algo."},{id:"pp2",group:"por-para",context:"Thank a friend for their help.",sentence:"Gracias ___ tu ayuda.",options:["por","para"],correct:0,hint:"What are you thanking them in exchange for?",why:"Gracias por: you thank someone for something they did."},{id:"pp3",group:"por-para",context:"Say who the gift is for.",sentence:"Este regalo es ___ mi mam\xe1.",options:["por","para"],correct:1,hint:"Who receives it?",why:"Para marks the recipient: el regalo es para mi mam\xe1."},{id:"pp4",group:"por-para",context:"Describe a walk through the park.",sentence:"Caminamos ___ el parque.",options:["por","para"],correct:0,hint:"Are you moving through a place?",why:"Por expresses movement through or around a place: caminamos por el parque."},{id:"pp5",group:"por-para",context:"Give a deadline at work.",sentence:"Necesito el reporte ___ el viernes.",options:["por","para"],correct:1,hint:"This is a deadline, a point in time.",why:"Para marks a deadline: para el viernes, by Friday."},{id:"pp6",group:"por-para",context:"Explain why a trip was cancelled.",sentence:"No fuimos ___ la lluvia.",options:["por","para"],correct:0,hint:"Is this a cause or a goal?",why:"Por gives the cause: no fuimos por la lluvia, because of the rain."}],n=[[{id:"a1",kind:"grammar",prompt:"Identify a relative\u2019s occupation: Mi t\xeda ___ enfermera.",options:["es","est\xe1"],correct:0,explanation:"Ser identifies a profession."},{id:"a2",kind:"grammar",prompt:"Report one finished event: Anoche Pedro ___ una carta y la envi\xf3.",options:["escrib\xeda","escribi\xf3"],correct:1,explanation:"Escribi\xf3 reports the completed letter-writing event."},{id:"a3",kind:"listening",prompt:"What will Marta bring?",audio:"Marta va a cenar con sus primos el viernes. Ellos preparan la comida y ella va a llevar pan. No va a llevar bebidas porque ya tienen agua.",options:["Drinks","Bread","Fruit"],correct:1,explanation:"Ella va a llevar pan."},{id:"a4",kind:"listening",prompt:"Why did the family stay inside?",audio:"El domingo quer\xedamos caminar por el barrio. Empez\xf3 a llover antes de salir, as\xed que nos quedamos en la sala y jugamos cartas.",options:["It started raining","They had to work","The car broke down"],correct:0,explanation:"Empez\xf3 a llover antes de salir."}],[{id:"b1",kind:"grammar",prompt:"Describe someone\u2019s state right now: Mi primo ___ preocupado hoy.",options:["es","est\xe1"],correct:1,explanation:"Estar describes his current state."},{id:"b2",kind:"grammar",prompt:"Describe a regular childhood habit: De ni\xf1a, Julia ___ al r\xedo cada verano.",options:["iba","fue"],correct:0,explanation:"Iba describes a repeated habit."},{id:"b3",kind:"listening",prompt:"When are they meeting?",audio:"La cena empieza a las siete, pero queremos ayudar antes. Nos vemos en casa de Rosa a las seis. Ella ya compr\xf3 todo.",options:["At five","At seven","At six"],correct:2,explanation:"Nos vemos ... a las seis."},{id:"b4",kind:"listening",prompt:"What did Carlos do when he did not understand?",audio:"Carlos escuch\xf3 una historia de su abuelo. No entendi\xf3 una frase, as\xed que le pidi\xf3 un ejemplo. Su abuelo explic\xf3 la frase y Carlos pudo seguir escuchando.",options:["He left the room","He asked for an example","He changed the subject"],correct:1,explanation:"Le pidi\xf3 un ejemplo."}],[{id:"c1",kind:"grammar",prompt:"Locate the keys: Las llaves ___ junto a la ventana.",options:["est\xe1n","son"],correct:0,explanation:"Estar locates physical objects."},{id:"c2",kind:"grammar",prompt:"A completed interruption: Nosotros habl\xe1bamos cuando ___ Elena.",options:["llegaba","lleg\xf3"],correct:1,explanation:"Lleg\xf3 marks the completed arrival interrupting the background."},{id:"c3",kind:"listening",prompt:"What did Luc\xeda learn to prepare?",audio:"Luc\xeda visit\xf3 a su t\xeda el s\xe1bado. Su t\xeda le ense\xf1\xf3 a preparar arroz. Primero mir\xf3 c\xf3mo lo hac\xeda y despu\xe9s lo intent\xf3 ella misma.",options:["Soup","Bread","Rice"],correct:2,explanation:"Le ense\xf1\xf3 a preparar arroz."},{id:"c4",kind:"listening",prompt:"What changed about the plan?",audio:"\xcdbamos a comer en el jard\xedn, pero hac\xeda mucho viento. Llevamos los platos a la cocina y comimos all\xed. La comida empez\xf3 a la misma hora.",options:["The place","The time","The guests"],correct:0,explanation:"They moved from the garden to the kitchen; the time stayed the same."}]],t=[{title:"Spacing \xb7 Kim & Webb (2022)",url:"https://doi.org/10.1111/lang.12479",finding:"A meta-analysis of 48 experiments supports spacing in L2 learning. Longer gaps helped delayed tests; equal and expanding schedules were statistically similar.",application:"Review across days. Our exact intervals are design choices, not a proven optimal schedule."},{title:"Retrieval \xb7 Karpicke & Roediger (2008)",url:"https://pubmed.ncbi.nlm.nih.gov/18276894/",finding:"Repeated retrieval of foreign-language vocabulary improved delayed retention beyond additional study after initial learning.",application:"Attempt before revealing. Assisted retries are separated from first-attempt evidence. Vocabulary experiments alone do not establish conversational fluency."},{title:"Feedback \xb7 Lyster & Saito (2010)",url:"https://doi.org/10.1017/S0272263109990520",finding:"A meta-analysis of 15 classroom studies found lasting benefits of oral corrective feedback, with larger effects for prompts than recasts.",application:"Offer a clue and a second attempt before showing a model. Applying classroom oral findings to app-based written prompts is an extrapolation."},{title:"Mixed practice \xb7 Pan et al. (2024)",url:"https://sc-pan.github.io/pdf/PRKL_2024.pdf",finding:"Across four experiments, interleaving improved conjugation performance on delayed tests; some identification skills also improved.",application:"Mix contextual grammar choices after a brief explanation. This does not imply every activity should always be mixed."},{title:"Reading \xb7 Sangers et al. (2025)",url:"https://doi.org/10.1007/s10648-025-10068-6",finding:"A meta-analysis found small-to-medium benefits of extensive reading across language outcomes. Foreign-language university learners were overrepresented.",application:"Offer easier texts, learner choice, and optional support. Four short app stories are a starting library, not an extensive-reading program."},{title:"Balanced practice \xb7 Nation (2007)",url:"https://doi.org/10.2167/illt039.0",finding:"The four-strands framework advocates meaning-focused input, output, language-focused work, and fluency development.",application:"A daily plan includes each strand. This is a curriculum framework, not a trial proving that an exact 25% split is optimal for you."},{title:"Repeated speaking \xb7 de Jong & Perfetti (2011)",url:"https://sites.pitt.edu/~perfetti/PDF/de%20Jong%20Language%20Learning.pdf",finding:"In a small study of 24 ESL students, repeated-topic 4/3/2-minute speeches supported maintained fluency gains.",application:"Retell familiar material in optional 60/45/30-second rounds. These shorter beginner timings are our adaptation, not a tested replication."},{title:"App evidence \xb7 mobile-learning meta-analysis (2022)",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC9479751/",finding:"A meta-analysis found favorable mobile-learning outcomes but high risk of bias and low-quality evidence across included studies.",application:"Research-informed features do not establish superiority over other apps. Track new-item results and real conversations, with honest measurement limits."}]},149,[]);
