__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"courseGrammar",{enumerable:!0,get:function(){return o}});const o={"everyday-intro":{title:"Ser: to be (who you are)",rule:"Ser says who or what someone is: name, job, where they are from. Each person has its own form, so you can usually drop yo, t\xfa, and so on.",forms:"soy \xb7 eres \xb7 es \xb7 somos \xb7 son",example:["Soy de Chicago y soy maestro.","I'm from Chicago and I'm a teacher."],questions:[{context:"You are a nurse.",sentence:"Yo ___ enfermera.",options:["soy","es","eres"],correct:0,why:"Soy goes with yo."},{context:"Ask a friend where they're from.",sentence:"\xbfDe d\xf3nde ___?",options:["eres","soy","son"],correct:0,why:"Eres is the t\xfa form: \xbfDe d\xf3nde eres?"},{context:"Ana and Luis are from Mexico.",sentence:"Ana y Luis ___ de M\xe9xico.",options:["somos","es","son"],correct:2,why:"Two people (ellos) take son."}]},"everyday-routine":{title:"The present tense: regular verbs",rule:"Drop -ar, -er, or -ir and add an ending for the person. -ar verbs use a; -er and -ir verbs use e. Only nosotros shows the difference between -er and -ir.",forms:"trabajo \xb7 trabajas \xb7 trabaja \xb7 trabajamos \xb7 trabajan\ncomo \xb7 comes \xb7 come \xb7 comemos \xb7 comen\nvivo \xb7 vives \xb7 vive \xb7 vivimos \xb7 viven",example:["Trabajo en casa y como a las dos.","I work at home and eat at two."],questions:[{context:"We eat at home.",sentence:"Nosotros ___ en casa.",options:["comemos","comimos","comen"],correct:0,why:"Comer \u2192 comemos for nosotros in the present."},{context:"Ask: Do you work on Saturdays?",sentence:"\xbf___ los s\xe1bados?",options:["Trabaja","Trabajas","Trabajo"],correct:1,why:"Trabajas is the t\xfa form."},{context:"My parents live in Puebla.",sentence:"Mis pap\xe1s ___ en Puebla.",options:["vive","vivimos","viven"],correct:2,why:"Ellos takes -en: viven."}]},"everyday-cafe":{title:"Por or para",rule:"Para points ahead: who something is for, a purpose, a destination (para m\xed, para llevar). Por points back or through: a reason, thanks, an exchange (gracias por, por la lluvia, por cien pesos).",example:["Un caf\xe9 para llevar, por favor.","A coffee to go, please."],tag:"por-para",questions:[{context:"The coffee is for you.",sentence:"El caf\xe9 es ___ ti.",options:["para","por"],correct:0,why:"A recipient takes para: para ti."},{context:"Thanks for the coffee.",sentence:"Gracias ___ el caf\xe9.",options:["para","por"],correct:1,why:"You give thanks for something with por: gracias por."},{context:"I'm saving to buy a coffee maker.",sentence:"Ahorro ___ comprar una cafetera.",options:["por","para"],correct:1,why:"A purpose (in order to) takes para + infinitive."}]},"everyday-time":{title:"Ir a + infinitive: what you're going to do",rule:"Conjugate ir, add a, then the verb as it is in the dictionary. It's the everyday way to talk about plans.",forms:"voy \xb7 vas \xb7 va \xb7 vamos \xb7 van",example:["Vamos a comer a las tres.","We're going to eat at three."],questions:[{context:"I'm going to call you tomorrow.",sentence:"Ma\xf1ana te ___ a llamar.",options:["va","voy","vas"],correct:1,why:"Voy is the yo form of ir."},{context:"Are you going to come?",sentence:"\xbfVas a ___?",options:["vienes","venir","vengo"],correct:1,why:"After ir a, the verb stays in the infinitive: venir."},{context:"They're going to arrive late.",sentence:"Ellos ___ a llegar tarde.",options:["van","vamos","va"],correct:0,why:"Ellos takes van."}]},"everyday-directions":{title:"Estar and hay: where things are",rule:"Estar says where a specific thing is: \xbfD\xf3nde est\xe1 el ba\xf1o? Hay says that something exists somewhere, often with un, una, or a number: Hay un banco cerca.",forms:"estoy \xb7 est\xe1s \xb7 est\xe1 \xb7 estamos \xb7 est\xe1n",example:["El metro est\xe1 a dos cuadras. Hay una farmacia enfrente.","The metro is two blocks away. There's a pharmacy across the street."],tag:"ser-estar",questions:[{context:"Where is the bathroom?",sentence:"\xbfD\xf3nde ___ el ba\xf1o?",options:["es","est\xe1","hay"],correct:1,why:"The location of a specific place takes estar."},{context:"Is there an ATM around here?",sentence:"\xbf___ un cajero por aqu\xed?",options:["Hay","Est\xe1","Es"],correct:0,why:"Asking whether one exists takes hay."},{context:"We are in the center.",sentence:"Nosotros ___ en el centro.",options:["somos","estamos","hay"],correct:1,why:"Where people are takes estar: estamos."}]},"everyday-shopping":{title:"Masculine and feminine",rule:"Every noun is masculine or feminine, and the words around it match: el/la, un/una, este/esta, and adjectives ending in -o/-a. Most nouns in -o are masculine and most in -a are feminine, but learn each one with its article.",example:["Esta camisa roja es m\xe1s barata que el su\xe9ter negro.","This red shirt is cheaper than the black sweater."],tag:"gender",questions:[{context:"This shirt (la camisa) is pretty.",sentence:"___ camisa es bonita.",options:["Este","Esta"],correct:1,why:"Camisa is feminine, so esta."},{context:"A small bag (la bolsa).",sentence:"Una bolsa ___.",options:["peque\xf1o","peque\xf1a"],correct:1,why:"The adjective matches bolsa: peque\xf1a."},{context:"The day was long. D\xeda is an exception.",sentence:"___ d\xeda fue largo.",options:["El","La"],correct:0,why:"D\xeda ends in -a but is masculine: el d\xeda."}]},"everyday-past":{title:"The preterite: what happened",rule:"For finished events. -ar verbs: -\xe9, -aste, -\xf3, -amos, -aron. -er and -ir verbs: -\xed, -iste, -i\xf3, -imos, -ieron. Ir and ser share fui; hacer becomes hice.",forms:"prepar\xe9 \xb7 preparaste \xb7 prepar\xf3 \xb7 preparamos \xb7 prepararon\ncom\xed \xb7 comiste \xb7 comi\xf3 \xb7 comimos \xb7 comieron",example:["Ayer prepar\xe9 tacos y com\xed con mi hermano.","Yesterday I made tacos and ate with my brother."],questions:[{context:"Yesterday I worked a lot.",sentence:"Ayer ___ mucho.",options:["trabajo","trabaj\xe9","trabaj\xf3"],correct:1,why:"Trabaj\xe9 is the yo preterite. Trabaj\xf3 is \xe9l/ella."},{context:"Did you eat already?",sentence:"\xbfYa ___?",options:["comiste","comes","com\xed"],correct:0,why:"Comiste is the t\xfa preterite."},{context:"On Saturday I went to the market.",sentence:"El s\xe1bado ___ al mercado.",options:["voy","fui","fue"],correct:1,why:"Ir in the preterite: fui for yo."}]},"everyday-repair":{title:"Question words",rule:"Question words carry an accent: qu\xe9, c\xf3mo, d\xf3nde, cu\xe1ndo, cu\xe1nto, qui\xe9n, por qu\xe9. The answer porque (because) is one word with no accent.",example:["\xbfQu\xe9 significa \xabchamba\xbb? \xbfC\xf3mo se dice \xabjob\xbb?","What does \u201cchamba\u201d mean? How do you say \u201cjob\u201d?"],questions:[{context:"How do you say \u201cfork\u201d?",sentence:"\xbf___ se dice \xabfork\xbb?",options:["Qu\xe9","C\xf3mo","D\xf3nde"],correct:1,why:"How do you say is \xbfC\xf3mo se dice\u2026?"},{context:"Why are you laughing?",sentence:"\xbf___ te r\xedes?",options:["Porque","Por qu\xe9"],correct:1,why:"Asking why: por qu\xe9, two words with an accent."},{context:"How much is it?",sentence:"\xbf___ cuesta?",options:["Cu\xe1nto","Cu\xe1ndo"],correct:0,why:"Cu\xe1nto is how much; cu\xe1ndo is when."}]},"everyday-plans":{title:"Verbs that change their stem",rule:"Some verbs change the vowel in the stem when it's stressed: e \u2192 ie (querer: quiero), o \u2192 ue (poder: puedo). Nosotros keeps the original vowel: queremos, podemos.",forms:"quiero \xb7 quieres \xb7 quiere \xb7 queremos \xb7 quieren\npuedo \xb7 puedes \xb7 puede \xb7 podemos \xb7 pueden",example:["\xbfQuieres ir al cine? Hoy no puedo, pero ma\xf1ana s\xed.","Do you want to go to the movies? I can't today, but tomorrow yes."],questions:[{context:"I can't go on Friday.",sentence:"No ___ ir el viernes.",options:["podo","puedo","pueda"],correct:1,why:"Poder changes o \u2192 ue: puedo."},{context:"Do you want to come?",sentence:"\xbf___ venir?",options:["Quieres","Queres","Quieren"],correct:0,why:"Querer changes e \u2192 ie in the t\xfa form: quieres."},{context:"We can meet at six.",sentence:"___ vernos a las seis.",options:["Puedemos","Podemos"],correct:1,why:"Nosotros keeps the stem vowel: podemos."}]},"everyday-people":{title:"Ser or estar",rule:"Ser describes what someone is like: personality, looks, job, origin. Estar describes how or where someone is right now: mood, health, location. Es aburrido means he's boring; est\xe1 aburrido means he's bored.",example:["Mi prima es muy alegre, pero hoy est\xe1 cansada.","My cousin is very cheerful, but today she's tired."],tag:"ser-estar",questions:[{context:"My brother is tall.",sentence:"Mi hermano ___ alto.",options:["es","est\xe1"],correct:0,why:"What someone looks like takes ser."},{context:"Your mom is at work right now.",sentence:"Tu mam\xe1 ___ en el trabajo.",options:["es","est\xe1"],correct:1,why:"Where someone is takes estar."},{context:"Ana is bored at the party.",sentence:"Ana ___ aburrida en la fiesta.",options:["es","est\xe1"],correct:1,why:"A state right now takes estar. Es aburrida would mean she's boring."}]},"everyday-feelings":{title:"Gustar and doler",rule:"With gustar and doler the thing does the action: me gusta el caf\xe9 (coffee pleases me). Use gusta or duele for one thing or an activity, and gustan or duelen for plural things. Never yo gusto.",forms:"me \xb7 te \xb7 le \xb7 nos \xb7 les + gusta / gustan",example:["Me gustan los tacos, pero me duele el est\xf3mago.","I like tacos, but my stomach hurts."],tag:"gustar",questions:[{context:"I like dogs.",sentence:"Me ___ los perros.",options:["gusta","gustan","gusto"],correct:1,why:"Los perros is plural, so gustan."},{context:"My feet hurt.",sentence:"Me ___ los pies.",options:["duele","duelen"],correct:1,why:"Plural body parts take duelen."},{context:"Do you like to dance?",sentence:"\xbfTe ___ bailar?",options:["gusta","gustan"],correct:0,why:"An activity (infinitive) takes gusta."}]},"everyday-messages":{title:"Estar + -ando/-iendo: right now",rule:"For something happening right this moment, use estar plus the -ing form: -ar \u2192 -ando, -er and -ir \u2192 -iendo. Estoy manejando means I'm driving (right now).",example:["Estoy saliendo del trabajo. \xbfQu\xe9 est\xe1s haciendo?","I'm leaving work. What are you doing?"],questions:[{context:"I'm eating now, I'll call you later.",sentence:"Estoy ___, te llamo luego.",options:["comiendo","comando","como"],correct:0,why:"Comer \u2192 comiendo."},{context:"We're waiting for you.",sentence:"Te ___ esperando.",options:["estamos","somos","vamos"],correct:0,why:"The -ando form goes with estar: estamos esperando."},{context:"What are you doing?",sentence:"\xbfQu\xe9 est\xe1s ___?",options:["hacer","haciendo","haces"],correct:1,why:"Hacer \u2192 haciendo."}]},"everyday-mexico":{title:"T\xfa or usted",rule:"Use t\xfa with friends, family, and people your age. Use usted with older people, strangers, and service staff in Mexico, especially at first. Usted takes the \xe9l/ella verb form: \xbfC\xf3mo est\xe1 usted?",example:["Disculpe, \xbfme puede ayudar?","Excuse me, can you help me? (usted)"],questions:[{context:"Ask an older stranger how they are.",sentence:"\xbfC\xf3mo ___ usted?",options:["est\xe1s","est\xe1"],correct:1,why:"Usted uses the \xe9l/ella form: est\xe1."},{context:"Ask a friend: Can you come?",sentence:"\xbf___ venir?",options:["Puedes","Puede"],correct:0,why:"With a friend, t\xfa: puedes."},{context:"Get a waiter's attention politely.",sentence:"___, \xbfme trae la cuenta?",options:["Disculpa","Disculpe"],correct:1,why:"Disculpe is the usted form, the safe choice with staff."}]},"everyday-childhood":{title:"Imperfect or preterite",rule:"The imperfect sets the scene and describes habits: -aba for -ar verbs, -\xeda for -er and -ir. The preterite tells what happened next. Era, iba, and ve\xeda are the only irregular imperfects.",forms:"jugaba \xb7 jugabas \xb7 jugaba \xb7 jug\xe1bamos \xb7 jugaban\nviv\xeda \xb7 viv\xedas \xb7 viv\xeda \xb7 viv\xedamos \xb7 viv\xedan",example:["Cuando era ni\xf1o, viv\xeda en Monterrey. Un d\xeda me ca\xed de un \xe1rbol.","When I was a kid, I lived in Monterrey. One day I fell out of a tree."],tag:"past",questions:[{context:"As a kid, I always played soccer (a habit).",sentence:"De ni\xf1o siempre ___ f\xfatbol.",options:["jugu\xe9","jugaba"],correct:1,why:"A repeated habit in the past takes the imperfect."},{context:"One day I broke a window (one event).",sentence:"Un d\xeda ___ una ventana.",options:["romp\xed","romp\xeda"],correct:0,why:"A single completed event takes the preterite."},{context:"It was raining when we arrived (background).",sentence:"___ cuando llegamos.",options:["Llovi\xf3","Llov\xeda"],correct:1,why:"Background going on at the time takes the imperfect."}]},"everyday-opinions":{title:"Comparing: m\xe1s, menos, tan",rule:"M\xe1s \u2026 que (more \u2026 than), menos \u2026 que (less \u2026 than), tan \u2026 como (as \u2026 as). Bueno and malo become mejor and peor: es mejor que\u2026",example:["El metro es m\xe1s r\xe1pido que el coche, pero menos c\xf3modo.","The metro is faster than the car, but less comfortable."],questions:[{context:"This one is better than the other.",sentence:"Este es ___ que el otro.",options:["m\xe1s bueno","mejor"],correct:1,why:"M\xe1s bueno becomes mejor."},{context:"Puebla is as pretty as Oaxaca.",sentence:"Puebla es tan bonita ___ Oaxaca.",options:["que","como"],correct:1,why:"Tan \u2026 como compares equals."},{context:"The bus is slower than the metro.",sentence:"El cami\xf3n es m\xe1s lento ___ el metro.",options:["que","como"],correct:0,why:"M\xe1s \u2026 que."}]},"everyday-advice":{title:"The conditional: would, should, could",rule:"Add -\xeda, -\xedas, -\xeda, -\xedamos, -\xedan to the whole infinitive. Deber, poder, and ir give deber\xedas (you should), podr\xedas (you could), ir\xeda (I would go). Tener and hacer shorten: tendr\xeda, har\xeda.",forms:"deber\xeda \xb7 deber\xedas \xb7 deber\xeda \xb7 deber\xedamos \xb7 deber\xedan",example:["Deber\xedas descansar. Yo que t\xfa, ir\xeda al m\xe9dico.","You should rest. If I were you, I'd go to the doctor."],questions:[{context:"You should sleep more.",sentence:"___ dormir m\xe1s.",options:["Deber\xedas","Deb\xedas","Deber\xe1s"],correct:0,why:"Advice uses the conditional: deber\xedas."},{context:"If I were you, I'd call her.",sentence:"Yo que t\xfa, la ___.",options:["llamar\xeda","llamaba","llamo"],correct:0,why:"Yo que t\xfa + conditional: llamar\xeda."},{context:"I'd do it, but I don't have time.",sentence:"Lo ___, pero no tengo tiempo.",options:["hacer\xeda","har\xeda"],correct:1,why:"Hacer shortens in the conditional: har\xeda."}]},"everyday-problems":{title:"Se me \u2026 : things that happened to you",rule:"For accidents, Spanish makes the thing the subject: se me olvid\xf3 la llave (the key slipped my mind). The verb matches the thing, so plural things take -aron: se me olvidaron las llaves.",forms:"se me \xb7 se te \xb7 se le \xb7 se nos \xb7 se les",example:["Se me rompi\xf3 el tel\xe9fono y se me perdieron los aud\xedfonos.","My phone broke and I lost my earphones."],questions:[{context:"I forgot my keys.",sentence:"Se me ___ las llaves.",options:["olvid\xf3","olvidaron"],correct:1,why:"Las llaves is plural, so olvidaron."},{context:"You dropped your wallet.",sentence:"Se ___ cay\xf3 la cartera.",options:["me","te","le"],correct:1,why:"For t\xfa: se te."},{context:"We missed the bus (it got away from us).",sentence:"Se ___ fue el cami\xf3n.",options:["nos","les"],correct:0,why:"For nosotros: se nos."}]},"everyday-wishes":{title:"The future tense",rule:"Add -\xe9, -\xe1s, -\xe1, -emos, -\xe1n to the whole infinitive: viajar\xe9 (I will travel). A few verbs shorten the stem: tener \u2192 tendr\xe9, hacer \u2192 har\xe9, poder \u2192 podr\xe9, salir \u2192 saldr\xe9. In speech, ir a + infinitive is more common for near plans.",forms:"viajar\xe9 \xb7 viajar\xe1s \xb7 viajar\xe1 \xb7 viajaremos \xb7 viajar\xe1n",example:["Alg\xfan d\xeda vivir\xe9 en la playa y tendr\xe9 un perro.","Someday I'll live at the beach and have a dog."],questions:[{context:"Someday I will speak Spanish well.",sentence:"Alg\xfan d\xeda ___ bien espa\xf1ol.",options:["hablar\xe9","habl\xe9","hablar\xeda"],correct:0,why:"Hablar\xe9 is the future for yo."},{context:"We will have more time.",sentence:"___ m\xe1s tiempo.",options:["Teneremos","Tendremos"],correct:1,why:"Tener shortens: tendremos."},{context:"Will you come to the party?",sentence:"\xbf___ a la fiesta?",options:["Vendr\xe1s","Venir\xe1s"],correct:0,why:"Venir shortens: vendr\xe1s."}]},"everyday-hopes":{title:"The present subjunctive",rule:"Take the yo form, drop -o, and swap the vowel: -ar verbs get e, -er and -ir verbs get a. Tengo \u2192 tenga, llego \u2192 llegue. Use it after que when you hope or want something for someone else.",forms:"tenga \xb7 tengas \xb7 tenga \xb7 tengamos \xb7 tengan",example:["Espero que tengas un buen viaje.","I hope you have a good trip."],questions:[{context:"I hope you arrive well.",sentence:"Espero que ___ bien.",options:["llegas","llegues"],correct:1,why:"Espero que + another person takes the subjunctive: llegues."},{context:"I want you to come.",sentence:"Quiero que ___.",options:["vengas","vienes","venir"],correct:0,why:"Vengo \u2192 venga \u2192 vengas for t\xfa."},{context:"I hope to arrive early (same person).",sentence:"Espero ___ temprano.",options:["llegue","llegar"],correct:1,why:"Same person: keep the infinitive."}]},"everyday-what-if":{title:"Si + imperfect subjunctive + conditional",rule:"For imagined situations: si + imperfect subjunctive, then the conditional. Build it from the preterite ellos form: drop -ron, add -ra. Tuvieron \u2192 tuviera, fueron \u2192 fuera.",forms:"tuviera \xb7 tuvieras \xb7 tuviera \xb7 tuvi\xe9ramos \xb7 tuvieran",example:["Si tuviera m\xe1s dinero, viajar\xeda por todo M\xe9xico.","If I had more money, I'd travel all over Mexico."],questions:[{context:"If I had time, I'd learn to cook.",sentence:"Si ___ tiempo, aprender\xeda a cocinar.",options:["tengo","tuviera","tendr\xeda"],correct:1,why:"Si + imperfect subjunctive: tuviera."},{context:"If you could live anywhere, where would you live?",sentence:"Si pudieras vivir en cualquier lugar, \xbfd\xf3nde ___?",options:["vivir\xedas","vivieras"],correct:0,why:"The other half takes the conditional: vivir\xedas."},{context:"If we were rich\u2026 (fueron \u2192 ?)",sentence:"Si ___ ricos\u2026",options:["fu\xe9ramos","ser\xedamos"],correct:0,why:"Fueron \u2192 fuera \u2192 fu\xe9ramos for nosotros."}]},"everyday-reported":{title:"Reporting what someone said",rule:"After dijo que, the tense moves back: present becomes imperfect (voy \u2192 iba), preterite stays or becomes pluperfect, and future becomes conditional (vendr\xe9 \u2192 vendr\xeda). Questions use pregunt\xf3 si.",example:["Me dijo que estaba cansada y que vendr\xeda ma\xf1ana.","She told me she was tired and would come tomorrow."],questions:[{context:"Luis said: \u201cTengo hambre.\u201d Report it.",sentence:"Luis dijo que ___ hambre.",options:["ten\xeda","tiene","tuvo"],correct:0,why:"Present tengo moves back to the imperfect: ten\xeda."},{context:"Ana said: \u201cLlamar\xe9 ma\xf1ana.\u201d",sentence:"Ana dijo que ___ al d\xeda siguiente.",options:["llamar\xe1","llamar\xeda"],correct:1,why:"The future moves back to the conditional: llamar\xeda."},{context:"He asked: \u201c\xbfVienes?\u201d",sentence:"Me pregunt\xf3 ___ ven\xeda.",options:["que","si"],correct:1,why:"A yes/no question is reported with si."}]},"everyday-debate":{title:"Creo que or no creo que",rule:"Creo que, pienso que, and es verdad que state what you believe, so they take the normal indicative. No creo que, dudo que, and no es verdad que express doubt, so they take the subjunctive: no creo que sea f\xe1cil.",example:["Creo que es buena idea, pero no creo que sea barato.","I think it's a good idea, but I don't think it's cheap."],questions:[{context:"I think it's true.",sentence:"Creo que ___ verdad.",options:["es","sea"],correct:0,why:"Creo que states a belief: indicative es."},{context:"I don't think they'll come.",sentence:"No creo que ___.",options:["vienen","vengan"],correct:1,why:"No creo que expresses doubt: subjunctive vengan."},{context:"I doubt he knows.",sentence:"Dudo que lo ___.",options:["sabe","sepa"],correct:1,why:"Dudo que takes the subjunctive: sepa."}]}}},151,[]);
