__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"dialogues",{enumerable:!0,get:function(){return o}});const o=[{id:"dinner-plan",title:"Confirm dinner plans",description:"Listen for times, clarify a detail, and offer to help.",start:"invitation",nodes:[{id:"invitation",speaker:"Ana",audio:"El domingo vamos a comer con mis t\xedos. La comida es a las dos, pero queremos llegar a la una y media para ayudar.",goal:"Confirm when you should arrive.",choices:[{text:"Entonces, \xbfllegamos a la una y media?",meaning:"So, do we arrive at one thirty?",feedback:"You checked the arrival time, which is earlier than the meal.",next:"bring"},{text:"\xbfA qu\xe9 hora llegamos? \xbfPuedes repetirlo?",meaning:"What time do we arrive? Can you repeat it?",feedback:"Asking for the specific detail you missed keeps the exchange moving.",next:"repeat"},{text:"Perfecto, llegamos a las dos y media.",meaning:"Perfect, we will arrive at two thirty.",feedback:"The time you proposed is later than the invitation. Listen to the correction.",next:"repeat"}]},{id:"repeat",speaker:"Ana",audio:"A la una y media. La comida empieza a las dos, pero vamos a llegar antes.",goal:"Check the corrected arrival time.",choices:[{text:"Ah, ya entend\xed. Llegamos a la una y media.",meaning:"Now I understand. We arrive at one thirty.",feedback:"You confirmed the important detail after clarification.",next:"bring"},{text:"Vamos a llegar antes de las dos, \xbfverdad?",meaning:"We are arriving before two, right?",feedback:"You checked the relationship between the arrival and meal times.",next:"bring"}]},{id:"bring",speaker:"Ana",audio:"Mi t\xeda va a preparar la comida. Nosotros podemos llevar algo de tomar o un postre.",goal:"Offer to bring dessert.",choices:[{text:"Yo puedo llevar el postre. \xbfLes gusta el pastel de chocolate?",meaning:"I can bring dessert. Do they like chocolate cake?",feedback:"You made an offer and asked a useful follow-up.",next:"done"},{text:"\xbfNecesitamos llegar a las dos?",meaning:"Do we need to arrive at two?",feedback:"The timing is already settled. Ana returns to the question of what to bring.",next:"offer"}]},{id:"offer",speaker:"Ana",audio:"La hora ya est\xe1. Ahora estamos viendo qu\xe9 llevar. \xbfPuedes llevar un postre?",goal:"Respond to the offer.",choices:[{text:"S\xed, claro. Voy a llevar un pastel.",meaning:"Of course. I will bring a cake.",feedback:"You brought the exchange back to the current topic.",next:"done"}]},{id:"done",speaker:"Ana",audio:"\xa1Perfecto! Nos vemos el domingo.",goal:"",choices:[],ending:"You confirmed a time and arranged what to bring. Try making a real plan with someone this week."}]},{id:"meal-help",title:"Help around the table",description:"Offer help and follow a short instruction.",start:"kitchen",nodes:[{id:"kitchen",speaker:"Se\xf1ora L\xf3pez",audio:"Ya casi est\xe1 la comida. Todav\xeda faltan los vasos y las servilletas en la mesa.",goal:"Offer to help with what is missing.",choices:[{text:"Yo pongo los vasos y las servilletas. \xbfD\xf3nde est\xe1n?",meaning:"I will put out the glasses and napkins. Where are they?",feedback:"You used the information in the request and asked where to find the items.",next:"location"},{text:"\xbfQu\xe9 falta en la mesa? No entend\xed la \xfaltima parte.",meaning:"What is missing from the table? I did not understand the last part.",feedback:"You specified the part you missed, which makes the repair easier.",next:"repeat"},{text:"Gracias, ya estoy lleno.",meaning:"Thank you, I am full.",feedback:"That phrase is useful after eating, but this conversation is about preparing the table.",next:"repeat"}]},{id:"repeat",speaker:"Se\xf1ora L\xf3pez",audio:"Faltan los vasos para el agua y las servilletas. \xbfMe ayudas a ponerlos?",goal:"Accept the request and ask where the items are.",choices:[{text:"S\xed, con gusto. \xbfD\xf3nde est\xe1n?",meaning:"Yes, gladly. Where are they?",feedback:"A short reply is enough to keep participating.",next:"location"}]},{id:"location",speaker:"Se\xf1ora L\xf3pez",audio:"Los vasos est\xe1n junto al fregadero y las servilletas est\xe1n en el caj\xf3n de arriba.",goal:"Confirm the location of the napkins.",choices:[{text:"\xbfLas servilletas est\xe1n en el caj\xf3n de arriba?",meaning:"Are the napkins in the top drawer?",feedback:"You checked one detail instead of guessing.",next:"done"},{text:"\xbfQu\xe9 significa fregadero?",meaning:"What does fregadero mean?",feedback:"Asking about a word can be part of completing the task.",next:"word"}]},{id:"word",speaker:"Se\xf1ora L\xf3pez",audio:"El fregadero es donde lavamos los platos. Los vasos est\xe1n al lado. Las servilletas est\xe1n en el caj\xf3n de arriba.",goal:"Show that you understand what to do.",choices:[{text:"Ah, ya entend\xed. Ahora pongo todo en la mesa.",meaning:"Now I understand. I will put everything on the table.",feedback:"You recovered the meaning and continued with the task.",next:"done"}]},{id:"done",speaker:"Se\xf1ora L\xf3pez",audio:"Muchas gracias por ayudarme.",goal:"",choices:[],ending:"You offered help and clarified an instruction. At the next meal, ask how you can help."}]},{id:"family-story",title:"Follow a family story",description:"Ask a relevant follow-up without needing every word.",start:"memory",nodes:[{id:"memory",speaker:"Don Roberto",audio:"Cuando era ni\xf1o, viv\xedamos cerca de un r\xedo. En verano mis hermanos y yo \xedbamos all\xed despu\xe9s de comer.",goal:"Invite him to tell you more about going to the river.",choices:[{text:"\xbfQu\xe9 les gustaba hacer en el r\xedo?",meaning:"What did you like to do at the river?",feedback:"You followed the topic and invited more detail.",next:"detail"},{text:"\xbfIban al r\xedo todos los d\xedas o solo a veces?",meaning:"Did you go every day or only sometimes?",feedback:"A concrete follow-up can be easier than a broad question.",next:"frequency"},{text:"\xbfA qu\xe9 hora vamos a comer hoy?",meaning:"What time are we eating today?",feedback:"That changes the subject. Listen for a chance to return to the memory.",next:"repair"}]},{id:"repair",speaker:"Don Roberto",audio:"Hoy comemos a las dos. Te estaba contando de cuando \xedbamos al r\xedo de ni\xf1os.",goal:"Return to his story.",choices:[{text:"Perd\xf3n, \xbfqu\xe9 hac\xedan en el r\xedo?",meaning:"Sorry, what did you do at the river?",feedback:"You returned to his topic with a clear question.",next:"detail"}]},{id:"frequency",speaker:"Don Roberto",audio:"Casi todos los d\xedas, si hac\xeda buen tiempo. Nos gustaba nadar y jugar en el agua.",goal:"Ask whether the water was cold.",choices:[{text:"\xbfEl agua estaba fr\xeda?",meaning:"Was the water cold?",feedback:"You picked a relevant detail from the setting.",next:"cold"}]},{id:"detail",speaker:"Don Roberto",audio:"Nos gustaba nadar. El agua estaba muy fr\xeda, pero no nos importaba.",goal:"Check or react to the meaning of the last part.",choices:[{text:"\xbfNo les importaba que el agua estuviera fr\xeda?",meaning:"You did not mind that the water was cold?",feedback:"You checked your interpretation. This is a useful chunk even before mastering all its grammar.",next:"cold"},{text:"No entend\xed \u201cno nos importaba\u201d. \xbfQu\xe9 quiere decir?",meaning:"I did not understand \u201cno nos importaba.\u201d What does it mean?",feedback:"You identified the exact phrase you needed help with.",next:"meaning"}]},{id:"meaning",speaker:"Don Roberto",audio:"Quiero decir que el agua fr\xeda no era un problema para nosotros. Quer\xedamos nadar de todos modos.",goal:"Acknowledge the explanation.",choices:[{text:"Ah, ya entend\xed. Quer\xedan nadar aunque hiciera fr\xedo.",meaning:"Now I understand. You wanted to swim even if it was cold.",feedback:"You paraphrased the meaning rather than repeating every word.",next:"done"}]},{id:"cold",speaker:"Don Roberto",audio:"S\xed, estaba fr\xeda, pero nos divert\xedamos mucho.",goal:"Respond to the memory.",choices:[{text:"\xa1Qu\xe9 bonito recuerdo! Gracias por cont\xe1rmelo.",meaning:"What a lovely memory! Thank you for telling me.",feedback:"You closed the story warmly.",next:"done"}]},{id:"done",speaker:"Don Roberto",audio:"Un d\xeda te ense\xf1o las fotos de ese lugar.",goal:"",choices:[],ending:"You followed the main topic and asked for meaning when needed. Try one follow-up question during a real story."}]},{id:"weekend-change",title:"Understand a changed plan",description:"Notice a change of place and respond to it.",start:"change",nodes:[{id:"change",speaker:"Marisol",audio:"\xcdbamos a ir al parque, pero parece que va a llover. Mejor nos vemos en casa de mi hermana.",goal:"Check the new meeting place.",choices:[{text:"Entonces, ya no vamos al parque. \xbfNos vemos en casa de tu hermana?",meaning:"So we are no longer going to the park. Are we meeting at your sister\u2019s house?",feedback:"You checked the change instead of relying on the original plan.",next:"address"},{text:"\xbfPor qu\xe9 cambiaron el plan?",meaning:"Why did you change the plan?",feedback:"You asked about the reason for the change.",next:"reason"},{text:"Nos vemos en el parque, entonces.",meaning:"See you at the park, then.",feedback:"That repeats the old plan. Listen to the corrected location.",next:"reason"}]},{id:"reason",speaker:"Marisol",audio:"Porque va a llover. Vamos a estar en casa de mi hermana, no en el parque.",goal:"Ask for the address of the new place.",choices:[{text:"Est\xe1 bien. \xbfMe puedes mandar la direcci\xf3n?",meaning:"Okay. Can you send me the address?",feedback:"You recovered the new plan and asked for what you need.",next:"address"}]},{id:"address",speaker:"Marisol",audio:"Te mando la direcci\xf3n por mensaje. La hora sigue igual: a las cuatro.",goal:"Confirm the time and thank her.",choices:[{text:"Perfecto, a las cuatro. Gracias por avisarme.",meaning:"Perfect, at four. Thanks for letting me know.",feedback:"You kept the changed location separate from the unchanged time.",next:"done"},{text:"Entonces, \xbftambi\xe9n cambi\xf3 la hora?",meaning:"So, did the time change too?",feedback:"This is another reasonable clarification request.",next:"time"}]},{id:"time",speaker:"Marisol",audio:"No, la hora no cambi\xf3. Nos vemos a las cuatro.",goal:"Confirm the time.",choices:[{text:"Entendido. Nos vemos a las cuatro.",meaning:"Understood. See you at four.",feedback:"You confirmed the plan after clarification.",next:"done"}]},{id:"done",speaker:"Marisol",audio:"\xa1Nos vemos! Maneja con cuidado.",goal:"",choices:[],ending:"You followed a change of plan and confirmed the details that mattered."}]},{id:"pharmacy",title:"Get advice at the pharmacy",description:"Describe how you feel, follow instructions, and check the dose.",start:"greet",nodes:[{id:"greet",speaker:"Farmac\xe9utica",audio:"Buenas tardes. \xbfEn qu\xe9 le puedo ayudar?",goal:"Explain your symptoms.",choices:[{text:"Buenas tardes. Me duele mucho la garganta y tengo un poco de fiebre.",meaning:"Good afternoon. My throat hurts a lot and I have a slight fever.",feedback:"You gave two clear symptoms, so she can help right away.",next:"since"},{text:"Necesito algo para la garganta.",meaning:"I need something for my throat.",feedback:"Clear and natural. She will ask for more detail.",next:"more"}]},{id:"more",speaker:"Farmac\xe9utica",audio:"Claro. \xbfLe duele al tragar? \xbfTiene fiebre?",goal:"Answer both questions.",choices:[{text:"S\xed, me duele al tragar, y creo que tengo un poco de fiebre.",meaning:"Yes, it hurts when I swallow, and I think I have a slight fever.",feedback:"You answered both questions she asked.",next:"since"}]},{id:"since",speaker:"Farmac\xe9utica",audio:"\xbfDesde cu\xe1ndo se siente as\xed?",goal:"Say how long it has been.",choices:[{text:"Desde ayer en la noche.",meaning:"Since last night.",feedback:"Desde + a time answers desde cu\xe1ndo directly.",next:"recommend"},{text:"Hace tres d\xedas.",meaning:"For three days (three days ago).",feedback:"Hace + time says how long ago it started.",next:"doctor"}]},{id:"doctor",speaker:"Farmac\xe9utica",audio:"Si ya son tres d\xedas con fiebre, le recomiendo ver a un m\xe9dico. Aqu\xed al lado hay un consultorio y la consulta es econ\xf3mica.",goal:"Respond to her recommendation.",choices:[{text:"Est\xe1 bien, voy al consultorio. Muchas gracias.",meaning:"Okay, I'll go to the clinic. Thank you very much.",feedback:"You followed the advice she gave.",next:"done"},{text:"Mientras tanto, \xbfqu\xe9 me recomienda para el dolor?",meaning:"In the meantime, what do you recommend for the pain?",feedback:"A good follow-up: mientras tanto means in the meantime.",next:"recommend"}]},{id:"recommend",speaker:"Farmac\xe9utica",audio:"Le doy estas pastillas para el dolor. T\xf3mese una cada ocho horas, con alimentos. Y tome mucha agua.",goal:"Check the dose.",choices:[{text:"Perd\xf3n, \xbfcada cu\xe1ntas horas?",meaning:"Sorry, every how many hours?",feedback:"Asking for the one number you missed is exactly right.",next:"repeat"},{text:"Entonces, una cada ocho horas, despu\xe9s de comer. \xbfVerdad?",meaning:"So, one every eight hours, after eating. Right?",feedback:"Repeating the instructions back is the safest way to check them.",next:"pay"}]},{id:"repeat",speaker:"Farmac\xe9utica",audio:"Cada ocho horas. Por ejemplo, a las ocho de la ma\xf1ana, a las cuatro de la tarde y a las doce de la noche.",goal:"Confirm and get ready to pay.",choices:[{text:"Ah, perfecto. \xbfCu\xe1nto es?",meaning:"Ah, perfect. How much is it?",feedback:"You confirmed and moved the conversation forward.",next:"pay"}]},{id:"pay",speaker:"Farmac\xe9utica",audio:"Son ochenta y cinco pesos. Que se mejore.",goal:"Thank her.",choices:[{text:"Gracias, muy amable.",meaning:"Thank you, that's very kind.",feedback:"Muy amable is a warm, polite thank-you.",next:"done"}]},{id:"done",speaker:"Farmac\xe9utica",audio:"Con mucho gusto. Hasta luego.",goal:"",choices:[],ending:"You described symptoms, said how long, and checked the dose before leaving."}]},{id:"plumber",title:"Call about a repair",description:"Explain a problem, understand ahorita, and agree on a time and price.",start:"answer",nodes:[{id:"answer",speaker:"Don Ram\xf3n",audio:"\xbfBueno? S\xed, aqu\xed Ram\xf3n, el plomero. \xbfQu\xe9 se le ofrece?",goal:"Explain the problem.",choices:[{text:"Buenos d\xedas, don Ram\xf3n. El boiler no funciona y no hay agua caliente.",meaning:"Good morning, Don Ram\xf3n. The water heater doesn't work and there's no hot water.",feedback:"You named the problem and what it causes. In Mexico the water heater is often el boiler.",next:"when"},{text:"Hola, tengo un problema con el agua.",meaning:"Hi, I have a problem with the water.",feedback:"A start, but he will need more detail.",next:"detail"}]},{id:"detail",speaker:"Don Ram\xf3n",audio:"\xbfQu\xe9 pasa con el agua? \xbfHay una fuga o no sale caliente?",goal:"Choose the right problem.",choices:[{text:"No sale caliente. Creo que es el boiler.",meaning:"It doesn't come out hot. I think it's the water heater.",feedback:"You chose between the two options he offered.",next:"when"}]},{id:"when",speaker:"Don Ram\xf3n",audio:"Ahorita estoy en otro trabajo, pero ahorita que termine paso con usted.",goal:"Find out what ahorita means here.",choices:[{text:"\xbfM\xe1s o menos a qu\xe9 hora puede venir?",meaning:"Roughly what time can you come?",feedback:"Smart: ahorita can mean soon or much later, so ask for a time.",next:"time"},{text:"Perfecto, lo espero ahora mismo.",meaning:"Perfect, I'll wait for you right now.",feedback:"Ahorita que termine means once he finishes, not right now.",next:"time"}]},{id:"time",speaker:"Don Ram\xf3n",audio:"Como a las tres de la tarde. Antes no puedo, la verdad.",goal:"Agree, then ask about the price.",choices:[{text:"Est\xe1 bien, a las tres. \xbfCu\xe1nto me va a cobrar?",meaning:"Okay, at three. How much will you charge me?",feedback:"Cobrar is to charge. Asking before the visit avoids surprises.",next:"price"}]},{id:"price",speaker:"Don Ram\xf3n",audio:"La revisi\xf3n son trescientos pesos. Si hay que cambiar una pieza, eso se paga aparte.",goal:"Check what is included.",choices:[{text:"Entiendo: trescientos por la revisi\xf3n, y las piezas aparte.",meaning:"I understand: three hundred for the inspection, and parts separately.",feedback:"You repeated both parts of the price.",next:"address"},{text:"\xbfTrescientos con todo incluido?",meaning:"Three hundred with everything included?",feedback:"Good to check. Listen for what he says about parts.",next:"clarify"}]},{id:"clarify",speaker:"Don Ram\xf3n",audio:"No, nada m\xe1s la revisi\xf3n. Las piezas se pagan aparte, pero le aviso antes.",goal:"Accept and give your address.",choices:[{text:"Muy bien. Le mando la direcci\xf3n por mensaje.",meaning:"Very good. I'll send you the address by message.",feedback:"You accepted the terms and handled the next step.",next:"address"}]},{id:"address",speaker:"Don Ram\xf3n",audio:"\xc1ndele, m\xe1ndeme la direcci\xf3n y ah\xed nos vemos a las tres.",goal:"Close the call.",choices:[{text:"Gracias, don Ram\xf3n. Hasta las tres.",meaning:"Thank you, Don Ram\xf3n. See you at three.",feedback:"A clear, friendly close with the time confirmed.",next:"done"}]},{id:"done",speaker:"Don Ram\xf3n",audio:"Hasta luego, que est\xe9 bien.",goal:"",choices:[],ending:"You explained a repair, pinned down what ahorita meant, and agreed on time and price."}]},{id:"work-meeting",title:"Share an idea at work",description:"Follow two coworkers, use usted with your boss, and give an opinion.",start:"open",nodes:[{id:"open",speaker:"Ingeniero Salas",audio:"Bueno, el proyecto va un poco atrasado. \xbfAlguien tiene una idea para terminarlo a tiempo?",goal:"Offer an idea to your boss politely.",choices:[{text:"Si me permite, creo que podr\xedamos dividir el trabajo en dos equipos.",meaning:"If you'll allow me, I think we could split the work into two teams.",feedback:"Si me permite and podr\xedamos make the idea polite for a boss.",next:"lupita"},{text:"Hay que trabajar m\xe1s horas.",meaning:"We have to work more hours.",feedback:"Clear, but blunt for a meeting. Listen to the reaction.",next:"hours"}]},{id:"hours",speaker:"Lupita",audio:"Uy, la verdad yo ya trabajo hasta las siete. No creo que m\xe1s horas sea la soluci\xf3n.",goal:"Respond to Lupita and offer another idea.",choices:[{text:"Tienes raz\xf3n. \xbfY si dividimos el trabajo en dos equipos?",meaning:"You're right. And what if we split the work into two teams?",feedback:"Tienes raz\xf3n acknowledges her; \xbfy si\u2026? offers an alternative.",next:"lupita"}]},{id:"lupita",speaker:"Lupita",audio:"Me parece buena idea. Yo puedo encargarme del dise\xf1o, si alguien m\xe1s ve lo de los clientes.",goal:"Offer to take the other part.",choices:[{text:"Yo me encargo de los clientes, entonces.",meaning:"I'll take care of the clients, then.",feedback:"Encargarse de: to be in charge of. You matched her structure.",next:"boss"},{text:"\xbfQu\xe9 tienes que hacer con los clientes, exactamente?",meaning:"What do you have to do with the clients, exactly?",feedback:"Asking for scope before agreeing is reasonable.",next:"scope"}]},{id:"scope",speaker:"Lupita",audio:"Nada m\xe1s contestar sus correos y hacer una llamada a la semana con cada uno.",goal:"Decide whether to take it.",choices:[{text:"Ah, s\xed puedo. Yo me encargo.",meaning:"Ah, yes, I can. I'll take care of it.",feedback:"S\xed puedo, with s\xed stressed, sounds confident.",next:"boss"}]},{id:"boss",speaker:"Ingeniero Salas",audio:"Muy bien. \xbfCree que pueden terminar para el viernes de la pr\xf3xima semana?",goal:"Answer your boss honestly, with usted.",choices:[{text:"Creo que s\xed, pero le aviso el mi\xe9rcoles c\xf3mo vamos.",meaning:"I think so, but I'll let you know on Wednesday how we're doing.",feedback:"Le aviso uses usted and promises an update. Very professional.",next:"done"},{text:"No estoy seguro. \xbfPodr\xedamos tener hasta el lunes?",meaning:"I'm not sure. Could we have until Monday?",feedback:"Honest and polite; podr\xedamos softens the request.",next:"monday"}]},{id:"monday",speaker:"Ingeniero Salas",audio:"Est\xe1 bien, el lunes. Pero el mi\xe9rcoles me dicen c\xf3mo van, por favor.",goal:"Agree to the update.",choices:[{text:"Claro, el mi\xe9rcoles le damos una actualizaci\xf3n.",meaning:"Of course, on Wednesday we'll give you an update.",feedback:"Le damos: we give you (usted). You agreed to his condition.",next:"done"}]},{id:"done",speaker:"Ingeniero Salas",audio:"Perfecto. Gracias a los dos.",goal:"",choices:[],ending:"You proposed an idea, split the work with a coworker, and committed to a date with your boss."}]}]},153,[]);
__d(function(g,r,_i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"lessons",{enumerable:!0,get:function(){return t}}),Object.defineProperty(e,"phrases",{enumerable:!0,get:function(){return s}});var o=r(d[0]);const t=[{id:"welcome",title:"Feel welcome",subtitle:"Introductions & first visits",principle:"Spanish often leaves out subject pronouns. Soy means I am, and estoy aprendiendo means I am learning. Use usted when you want to be respectful; follow the family\u2019s lead on t\xfa.",mission:"Greet someone, thank them for inviting you, and tell them you are learning Spanish.",story:"Hoy voy a conocer a la familia de mi novia. Estoy un poco nervioso, pero tengo muchas ganas de conocerlos. Su mam\xe1 me dice: \u201cBienvenido, est\xe1s en tu casa\u201d. Le doy las gracias por invitarme.",question:"How does the narrator feel before the visit?",options:["A little nervous, but eager to meet them","Angry about the invitation","Too tired to visit"],correct:0,explanation:"Estoy un poco nervioso = I am a little nervous. Tengo muchas ganas = I am really looking forward to it.",turns:[{prompt:"Her mother welcomes you: \u201c\xa1Qu\xe9 bueno que viniste!\u201d Thank her for the invitation.",example:"Muchas gracias por invitarme. Me da mucho gusto estar aqu\xed.",hint:"Start with gracias por\u2026"},{prompt:"A relative asks: \u201c\xbfHablas espa\xf1ol?\u201d Explain that you are learning.",example:"Estoy aprendiendo espa\xf1ol. Todav\xeda me cuesta un poco.",hint:"Estoy aprendiendo\u2026"},{prompt:"Ask someone their name, politely.",example:"\xbfC\xf3mo se llama usted?",hint:"Use usted with se llama."}]},{id:"table",title:"Around the table",subtitle:"Food, offers & appreciation",principle:"Use est\xe1 to describe how food tastes right now: est\xe1 muy rico. Me gusta means I like it; me gustan takes a plural thing: me gustan los tacos. Requests with \xbfMe pasas\u2026? are familiar; \xbfMe pasa\u2026? uses usted.",mission:"Offer to help, compliment the meal, and ask someone to pass one thing.",story:"La mam\xe1 de Ana prepara pozole para la comida. Yo ayudo a poner la mesa. El pozole est\xe1 muy rico, pero la salsa pica mucho. Ana me pasa un vaso de agua. Despu\xe9s todos ayudamos a recoger.",question:"Why does Ana pass the narrator water?",options:["The pozole is cold","The salsa is very spicy","They are leaving soon"],correct:1,explanation:"La salsa pica mucho means the salsa is very spicy. Picar here describes spicy heat.",turns:[{prompt:"The family is preparing dinner. Offer to help.",example:"\xbfPuedo ayudar en algo? Puedo poner la mesa.",hint:"\xbfPuedo ayudar\u2026?"},{prompt:"You like the food. Compliment it and ask what it is called.",example:"Est\xe1 muy rico. \xbfC\xf3mo se llama este platillo?",hint:"Est\xe1 muy rico\u2026"},{prompt:"Ask a relative to pass the salsa.",example:"\xbfMe pasas la salsa, por favor?",hint:"\xbfMe pasas\u2026?"}]},{id:"repair",title:"Keep the conversation going",subtitle:"Ask, clarify & recover",principle:"Asking for clarification is a conversation skill. \xbfPuede repetir? is formal; \xbfpuedes repetir? is familiar. Use \xbfQuieres decir que\u2026? to check an interpretation, not just to ask for the same words again.",mission:"When you miss something, ask for a slower repeat instead of switching immediately to English.",story:"El t\xedo de Ana cuenta una historia muy r\xe1pido. No entiendo una palabra y le pregunto qu\xe9 significa. \xc9l me la explica con un ejemplo. Entonces le digo: \u201cAh, ya entend\xed\u201d. Sigue contando y ahora puedo seguir la historia.",question:"What helps the narrator understand the unknown word?",options:["Changing to another topic","Reading a dictionary alone","An explanation with an example"],correct:2,explanation:"\xc9l me la explica con un ejemplo = He explains it to me with an example.",turns:[{prompt:"Someone speaks too quickly. Politely ask them to slow down.",example:"\xbfPuede hablar m\xe1s despacio, por favor?",hint:"M\xe1s despacio means more slowly."},{prompt:"You heard a new word. Ask what it means.",example:"\xbfQu\xe9 significa esa palabra?",hint:"\xbfQu\xe9 significa\u2026?"},{prompt:"You think they said the meal starts at six. Check that understanding.",example:"Entonces, \xbfcomemos a las seis?",hint:"Entonces\u2026 followed by your interpretation."}]},{id:"week",title:"Tell them about your week",subtitle:"Past events & follow-up questions",principle:"For completed events, use the preterite: trabaj\xe9 (I worked), fui (I went), hice (I did). The imperfect describes a background or habit: trabajaba (I used to work / was working). Start with one concrete event and a follow-up question.",mission:"Share two things you did this week, then ask someone about their weekend.",story:"El s\xe1bado trabaj\xe9 por la ma\xf1ana. Por la tarde fui al parque con mi novia y caminamos un rato. El domingo nos quedamos en casa porque llovi\xf3. Cocinamos juntos y vimos una pel\xedcula.",question:"Why did they stay home on Sunday?",options:["It rained","They worked all day","The park was too far away"],correct:0,explanation:"Nos quedamos en casa porque llovi\xf3 = We stayed home because it rained.",turns:[{prompt:"Someone asks: \u201c\xbfQu\xe9 hiciste el fin de semana?\u201d Say you went to the park.",example:"Fui al parque con mi novia. Caminamos un rato.",hint:"Fui al\u2026"},{prompt:"Ask them what they did on Sunday.",example:"\xbfQu\xe9 hiciste el domingo?",hint:"Hiciste is the t\xfa form of hacer."},{prompt:"They say they saw a movie. Ask whether they liked it.",example:"\xbfTe gust\xf3 la pel\xedcula?",hint:"Gust\xf3 refers to a completed past experience."}]},{id:"stories",title:"Get to know their story",subtitle:"Family, hometowns & memories",principle:"For memories and descriptions, era and hab\xeda are useful: era peque\xf1o (it was small), hab\xeda un parque (there was a park). Ask open questions, then follow up with \xbfy despu\xe9s? or \xbfc\xf3mo fue? Avoid assuming someone wants to discuss migration.",mission:"Ask about a hometown, favorite childhood meal, or family tradition. Let them choose how much to share.",story:"La abuela me cuenta que de ni\xf1a viv\xeda en un pueblo peque\xf1o. Hab\xeda una plaza donde jugaba con sus hermanos. Los domingos su familia com\xeda en casa de sus abuelos. Dice que todav\xeda prepara la sopa que hac\xeda su mam\xe1.",question:"What does the grandmother still prepare?",options:["A dish she learned at work","The soup her mother used to make","Only food from restaurants"],correct:1,explanation:"Todav\xeda prepara la sopa que hac\xeda su mam\xe1 = She still makes the soup her mother used to make.",turns:[{prompt:"Ask an older relative what their hometown was like, using usted.",example:"\xbfC\xf3mo era su pueblo?",hint:"Su, rather than tu, when using usted."},{prompt:"They mention a favorite family dish. Ask who taught them to make it.",example:"\xbfQui\xe9n le ense\xf1\xf3 a prepararlo?",hint:"\xbfQui\xe9n le ense\xf1\xf3\u2026?"},{prompt:"They are telling a story. Invite them to continue.",example:"\xbfY qu\xe9 pas\xf3 despu\xe9s?",hint:"Despu\xe9s means afterward."}]},{id:"plans",title:"Make plans together",subtitle:"Invitations, timing & preferences",principle:"Voy a + infinitive describes a plan: voy a llevar postre. We are going to is vamos a. Use \xbfa qu\xe9 hora? for at what time, and \xbfd\xf3nde? for where. Ustedes is the plural you used in Mexico.",mission:"Arrange a simple plan: ask the time, offer to bring something, and confirm where to meet.",story:"El pr\xf3ximo domingo vamos a comer en casa de los t\xedos de Ana. La comida empieza a las dos, pero vamos a llegar a la una para ayudar. Yo voy a llevar el postre. Despu\xe9s, si hace buen tiempo, vamos a caminar.",question:"When do they plan to arrive?",options:["At two, when the meal starts","After the walk","At one, to help beforehand"],correct:2,explanation:"Vamos a llegar a la una para ayudar = We are going to arrive at one to help.",turns:[{prompt:"You are invited for Sunday. Ask what time to arrive.",example:"\xbfA qu\xe9 hora llegamos?",hint:"\xbfA qu\xe9 hora\u2026?"},{prompt:"Offer to bring dessert.",example:"Voy a llevar el postre. \xbfEst\xe1 bien?",hint:"Voy a llevar\u2026"},{prompt:"Confirm that you will see everyone on Sunday.",example:"Entonces, nos vemos el domingo.",hint:"Nos vemos\u2026"}]}];t.push(...o.courseLessons);const s=[...Object.entries({welcome:[["Thank you for inviting me.","Gracias por invitarme.","After por, use the infinitive. Me attaches to invitar.",["Muchas gracias por invitarme."]],["I am learning Spanish.","Estoy aprendiendo espa\xf1ol.","Estar + gerund describes an ongoing action."],["It is a pleasure to meet you.","Mucho gusto.","A common greeting on meeting someone.",["Es un gusto conocerte.","Es un gusto conocerlo.","Es un gusto conocerla."]],["What is your name? (formal)","\xbfC\xf3mo se llama usted?","With t\xfa: \xbfC\xf3mo te llamas?",["\xbfC\xf3mo se llama?"]],["I am a little nervous.","Estoy un poco nervioso.","Use nerviosa if that adjective fits you.",["Estoy un poco nerviosa."]],["I am very happy to be here.","Me da mucho gusto estar aqu\xed.","Me da gusto expresses pleasure.",["Estoy muy contento de estar aqu\xed.","Estoy muy contenta de estar aqu\xed."]],["I am her boyfriend.","Soy su novio.","Soy identifies who you are. Su can mean her, his, or your (formal), depending on context."],["Spanish is still a little difficult for me.","Todav\xeda me cuesta un poco el espa\xf1ol.","Me cuesta means I find it difficult."]],table:[["Everything is delicious.","Todo est\xe1 muy rico.","Rico commonly describes tasty food in Mexico.",["Todo est\xe1 delicioso."]],["Can I help with anything?","\xbfPuedo ayudar en algo?","Use puedo + infinitive."],["Could you pass me the salsa, please? (familiar)","\xbfMe pasas la salsa, por favor?","With usted: \xbfMe pasa la salsa, por favor?"],["What is this dish called?","\xbfC\xf3mo se llama este platillo?","Platillo is common in Mexico for a prepared dish.",["\xbfC\xf3mo se llama este plato?"]],["Is it very spicy?","\xbfPica mucho?","Picar means to be spicy in this context.",["\xbfEst\xe1 muy picante?"]],["Just a little, please.","Solo un poco, por favor.","Useful when someone offers more food.",["Solamente un poco, por favor."]],["I can set the table.","Puedo poner la mesa.","Poner la mesa means to set the table."],["Thank you, I am full.","Gracias, ya estoy lleno.","Use llena if that adjective fits you.",["Gracias, ya estoy llena."]]],repair:[["Could you repeat that, please? (formal)","\xbfPuede repetir eso, por favor?","Use puedes with t\xfa."],["Could you speak more slowly? (formal)","\xbfPuede hablar m\xe1s despacio?","Despacio means slowly.",["\xbfPuede hablar m\xe1s despacio, por favor?"]],["What does that word mean?","\xbfQu\xe9 significa esa palabra?","Esa points to the word someone just used."],["How do you say this in Spanish?","\xbfC\xf3mo se dice esto en espa\xf1ol?","A useful phrase for learning during conversations."],["I did not understand the last part.","No entend\xed la \xfaltima parte.","Entend\xed is a completed past action."],["Could you give me an example? (formal)","\xbfMe puede dar un ejemplo?","Me can come before puede or attach to dar.",["\xbfPuede darme un ejemplo?"]],["Oh, now I understand.","Ah, ya entend\xed.","Ya can mean now or already, depending on context."],["So, are we eating at six?","Entonces, \xbfcomemos a las seis?","Repeating a concrete detail checks understanding."]],week:[["This week I worked a lot.","Esta semana trabaj\xe9 mucho.","The accent in trabaj\xe9 marks the first-person preterite."],["Yesterday I went to the park.","Ayer fui al parque.","Fui is the past of ir here. A + el becomes al."],["What did you do this weekend? (familiar)","\xbfQu\xe9 hiciste este fin de semana?","Hiciste is the t\xfa preterite of hacer."],["We stayed home.","Nos quedamos en casa.","Quedarse means to stay."],["We watched a movie.","Vimos una pel\xedcula.","Vimos is the nosotros preterite of ver."],["Did you like the movie? (familiar)","\xbfTe gust\xf3 la pel\xedcula?","Gust\xf3 agrees with the singular pel\xedcula."],["We went for a walk.","Fuimos a caminar.","Fuimos is the nosotros preterite of ir.",["Salimos a caminar."]],["And how was your week? (familiar)","\xbfY c\xf3mo estuvo tu semana?","A natural follow-up question.",["\xbfY qu\xe9 tal estuvo tu semana?"]]],stories:[["What was your hometown like? (formal)","\xbfC\xf3mo era su pueblo?","Use ciudad instead of pueblo if it was a city.",["\xbfC\xf3mo era su ciudad?"]],["What did you like to do as a child? (formal)","\xbfQu\xe9 le gustaba hacer de ni\xf1o?","Use de ni\xf1a when speaking to a woman.",["\xbfQu\xe9 le gustaba hacer de ni\xf1a?"]],["How did you two meet?","\xbfC\xf3mo se conocieron?","Ustedes is the plural you in Mexico."],["And what happened next?","\xbfY qu\xe9 pas\xf3 despu\xe9s?","An invitation to continue the story."],["Who taught you to prepare it? (formal)","\xbfQui\xe9n le ense\xf1\xf3 a prepararlo?","Prepararla refers to a feminine noun, such as sopa.",["\xbfQui\xe9n le ense\xf1\xf3 a prepararla?"]],["There was a park near the house.","Hab\xeda un parque cerca de la casa.","Hab\xeda describes what existed in the background."],["We used to eat together on Sundays.","Com\xedamos juntos los domingos.","The imperfect describes a repeated past activity."],["What a lovely memory!","\xa1Qu\xe9 bonito recuerdo!","Qu\xe9 + adjective + noun expresses a reaction."]],plans:[["What time should we arrive?","\xbfA qu\xe9 hora llegamos?","Present tense can express a future arrangement.",["\xbfA qu\xe9 hora debemos llegar?"]],["I am going to bring dessert.","Voy a llevar el postre.","Ir a + infinitive expresses a plan.",["Voy a llevar postre."]],["Shall we meet here?","\xbfNos vemos aqu\xed?","Nos vemos can make or confirm a plan."],["See you on Sunday.","Nos vemos el domingo.","Spanish uses el before a particular day."],["What would you like me to bring? (formal)","\xbfQu\xe9 quiere que lleve?","Lleve is subjunctive after quiere que. Learn the useful chunk first."],["I would rather arrive early.","Prefiero llegar temprano.","Preferir changes e to ie in prefiero."],["If the weather is nice, we can walk.","Si hace buen tiempo, podemos caminar.","Hace buen tiempo describes good weather."],["Let me know if the plan changes. (familiar)","Av\xedsame si cambia el plan.","Av\xedsame is a familiar command with me attached."]]}).flatMap(([o,t])=>t.map(([t,s,i,n],l)=>({id:`${o}-${l+1}`,lesson:o,en:t,es:s,note:i,alternatives:n}))),...o.coursePhrases]},154,[143]);
